  'Selectie opheffen': 'Hapus pilihan',
  'Ik ga akkoord met de EUPL 1.2-licentie en heb gelezen welke gegevens OciDeck bewaart.':
      'Saya menerima lisensi EUPL 1.2 dan telah membaca data apa yang disimpan OciDeck.',
  'Je keuze wordt de standaardtaal van de app.':
      'Pilihan Anda menjadi bahasa default aplikasi.',
  'Lees de volledige licentie': 'Baca lisensi lengkap',
  'OciDeck is vrije software onder de EUPL 1.2-licentie. Voordat je begint, vragen we je de licentie te accepteren. Hieronder lees je ook welke gegevens OciDeck op dit apparaat bewaart en wanneer er iets je apparaat verlaat.':
      'OciDeck adalah perangkat lunak bebas di bawah lisensi EUPL 1.2. Sebelum Anda mulai, kami meminta Anda untuk menerima lisensi tersebut. Di bawah ini Anda juga dapat membaca data apa yang disimpan OciDeck di perangkat ini dan kapan sesuatu meninggalkan perangkat Anda.',
  'OciDeck verzamelt geen statistieken en stuurt uit zichzelf niets naar buiten. Standaard blijft alles op dit apparaat. Gegevens verlaten dit apparaat alleen als jij dat kiest:\n\n•  Nextcloud/WebDAV: verbind je met een server, dan worden je inlognaam en wachtwoord bewaard (het wachtwoord veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die server verstuurd.\n•  Openen via URL: OciDeck haalt het bestand op van het adres dat je invoert.\n•  Online media (staat standaard uit): indien ingeschakeld laadt OciDeck afbeeldingen en video\'s van de adressen in je dia\'s.\n•  Externe links (zoals de online licentie) openen in je browser.':
      'OciDeck tidak mengumpulkan statistik dan tidak mengirim apa pun ke luar dengan sendirinya. Secara default semuanya tetap di perangkat ini. Data hanya meninggalkan perangkat ini jika Anda memilihnya:\n\n•  Nextcloud/WebDAV: saat Anda terhubung ke server, nama pengguna dan kata sandi Anda disimpan (kata sandi secara aman di keychain sistem Anda) dan presentasi yang Anda buka atau simpan dikirim ke server tersebut.\n•  Buka melalui URL: OciDeck mengambil berkas dari alamat yang Anda masukkan.\n•  Media daring (nonaktif secara default): jika diaktifkan, OciDeck memuat gambar dan video dari alamat di slide Anda.\n•  Tautan eksternal (seperti lisensi daring) terbuka di peramban Anda.',
  'OciDeck wordt geleverd onder de European Union Public Licence v1.2. Door akkoord te gaan aanvaard je deze licentie. Je mag OciDeck gebruiken, kopiëren, aanpassen en verspreiden onder de voorwaarden van de EUPL 1.2.':
      'OciDeck disediakan di bawah European Union Public Licence v1.2. Dengan menyetujui, Anda menerima lisensi ini. Anda boleh menggunakan, menyalin, memodifikasi, dan mendistribusikan OciDeck sesuai ketentuan EUPL 1.2.',
  'Om te werken en je werk niet te verliezen, bewaart OciDeck gegevens lokaal op dit apparaat:\n\n•  Je instellingen en voorkeuren (taal, mappen, stijl- en weergaveprofielen, recente bestanden).\n•  Je presentatiematerialen: de presentaties die je opslaat, automatische herstelkopieën en bijlagen zoals afbeeldingsbeschrijvingen.\n•  Deze toestemmingskeuze.\n\nJe kunt dit verwijderen door de bestanden te wissen of de instellingen te resetten.':
      'Untuk bekerja dan menjaga pekerjaan Anda tetap aman, OciDeck menyimpan data secara lokal di perangkat ini:\n\n•  Pengaturan dan preferensi Anda (bahasa, folder, profil gaya dan tampilan, berkas terbaru).\n•  Materi presentasi Anda: presentasi yang Anda simpan, salinan pemulihan otomatis, dan lampiran seperti deskripsi gambar.\n•  Pilihan persetujuan ini.\n\nAnda dapat menghapusnya dengan menghapus berkas atau mengatur ulang pengaturan.',
