  'Thema, slides, footer, checklist en titels over afbeeldingen, getoetst aan WCAG AA (4,5:1 voor tekst, 3:1 voor grote tekst).':
      'Tema, slide, footer, checklist, dan judul di atas gambar, diperiksa terhadap WCAG AA (4,5:1 untuk teks, 3:1 untuk teks besar).',
  'Elke afbeelding, grafiek, video en audio heeft een beschrijving nodig voor schermlezers en bijsluiters.':
      'Setiap gambar, grafik, video, dan audio memerlukan deskripsi untuk pembaca layar dan handout.',
  'Verwijzingen naar afbeeldingen, video en audio worden gecontroleerd op een bestaand bestand in het project.':
      'Referensi ke gambar, video, dan audio diperiksa untuk berkas yang ada di dalam proyek.',
  'Aantal en lengte van bullets, woorden, nesting, kolombalans en de dichtheid van quotes, titels, tabellen en code zodat alles leesbaar past.':
      'Jumlah dan panjang bullet, kata, penyusunan bertingkat, keseimbangan kolom, serta kepadatan kutipan, judul, tabel, dan kode agar semuanya pas terbaca.',
  'Bodytekst met contrast onder {crit}:1 telt als fout; daarboven tot de AA-norm als waarschuwing.':
      'Teks isi dengan kontras di bawah {crit}:1 dihitung sebagai kesalahan; di atasnya hingga norma AA sebagai peringatan.',
  'Geen drempelwaarde: een niet-lege beschrijving is verplicht.':
      'Tanpa ambang batas: deskripsi yang tidak kosong wajib diisi.',
  'Geen drempelwaarde: het gekoppelde bestand moet binnen de projectmap bestaan.':
      'Tanpa ambang batas: berkas yang ditautkan harus ada di dalam folder proyek.',
  'Waarschuwing boven {b1} bullets (1 kolom), {bcl} (checklist) of {b2} (2 kolommen); kritiek boven {bc1} of {bc2}. Woorden boven {w1}/{w2}, gemiddeld boven {avg} per bullet. Quote boven {q} tekens, titel boven {t} tekens. Nesting dieper dan niveau {lvl}. Tekst die tot onder {warn}% moet krimpen waarschuwt, onder {crit}% is kritiek.':
      'Peringatan di atas {b1} bullet (1 kolom), {bcl} (checklist) atau {b2} (2 kolom); kritis di atas {bc1} atau {bc2}. Kata di atas {w1}/{w2}, rata-rata di atas {avg} per bullet. Kutipan di atas {q} karakter, judul di atas {t} karakter. Penyusunan bertingkat lebih dalam dari level {lvl}. Teks yang harus menyusut di bawah {warn}% memberi peringatan, di bawah {crit}% adalah kritis.',
