  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Angka bagan tidak tersimpan — sekarang hanya ada di jendela ini:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Di peramban tidak ada pemulihan setelah crash: jika kamu menutup tab ini, pekerjaan yang belum tersimpan akan hilang. Simpan sendiri presentasimu.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Basis data CVE lokal (Anda sendiri yang memulai unduhan): OciDeck mengambil data massal melalui api.github.com dan berkas rilis yang ditunjuk alamat itu.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Pencarian CVE (mati secara bawaan): jika dinyalakan, kata pencarian Anda dikirim ke cermin CVE yang disetel dan, jika tidak menemukan apa pun, ke basis data Eropa ENISA dan ke MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Video YouTube atau Vimeo yang disematkan memuat pemutar dari layanan tersebut.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Di peramban: jika peramban menolak mengambil sebuah alamat secara langsung, OciDeck mencobanya lagi melalui server asal aplikasi; alamat itu lalu sampai ke server tersebut.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Pencabutan tidak tersimpan. Pada peluncuran berikutnya persetujuan Anda berlaku lagi.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Subjudul bagian yang mengumumkan bagian baru presentasi. Buat singkat. Tambahkan gambar latar dari pustaka gambar.',
  'Bronnen doorzoeken…': 'Menelusuri sumber…',
  'Niet doorzocht': 'Tidak ditelusuri',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Pemeriksaan ini tidak berjalan di versi web: deteksi wajah memerlukan pustaka sistem yang tidak dimiliki peramban. Gunakan versi desktop untuk memeriksa wajah pada gambar.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Token perlu akses baca dan tulis ke repositori. Gitea dan Forgejo tidak punya pencarian sisi server; OciDeck mencari secara lokal.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Token perlu cakupan repo (atau rinci: Contents baca dan tulis).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Token perlu read_repository, write_repository dan read_api. Pencarian sisi server memerlukan Advanced atau Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Pencarian sisi server yang cepat — karena jeda pengindeksan, dek yang baru diubah bisa terlewat.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Media tidak tersimpan dalam berkas .md biasa',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Gambar, video, dan audio yang kamu pilih di tab ini hanya ada di memori. Berkas .md biasa tidak menyimpannya — semuanya hilang saat dibuka kembali. Ekspor sebagai paket .ocideck untuk membawa medianya.',
  'Media verwijderd om privacyredenen': 'Media dihapus karena alasan privasi',
  'Afbeeldingen door AI laten taggen?':
      'Biarkan AI menandai gambar-gambar ini?',
