  'bedrijfsnummer (BN)': 'nomor perusahaan (BN)',
  'zorgverlenersnummer (NPI)': 'nomor penyedia layanan kesehatan (NPI)',
  'Medicare-nummer (MBI) — een zorggegeven':
      'nomor Medicare (MBI) — data kesehatan',
  'wacht op verbinding': 'menunggu koneksi',
  'Opgeslagen op deze computer, nog niet in de repository. Gaat mee zodra er weer verbinding is — of nu, met "Wachtrij legen".':
      'Disimpan di komputer ini, belum ada di repositori. Akan ikut begitu ada koneksi lagi — atau sekarang, dengan "Kosongkan antrean".',
  'Branch (optioneel)': 'Cabang (opsional)',
  'let op: de standaardbranch is': 'perhatian: cabang bawaan adalah',
  'jij werkt op': 'Anda bekerja di',
  'werkgeversnummer (EIN)': 'nomor pemberi kerja (EIN)',
  'laatste vier cijfers van een SSN': 'empat digit terakhir SSN',
  'geboortedatum, postcode en geslacht samen — die drie wijzen meestal één persoon aan, ook zonder naam':
      'tanggal lahir, kode pos, dan jenis kelamin bersama-sama — ketiganya biasanya menunjuk satu orang, bahkan tanpa nama',
  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Sertifikat server ini tidak tepercaya. Pada server yang di-host sendiri Anda dapat melihatnya dan memercayainya di Pengaturan → Penyimpanan.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Sertifikat forge ini tidak tepercaya. Pada forge yang di-host sendiri Anda dapat melihatnya dan memercayainya di Pengaturan → Penyimpanan.',
  'Het certificaat van het endpoint wordt niet vertrouwd. Bij een zelf gehost endpoint kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Sertifikat endpoint ini tidak tepercaya. Pada endpoint yang di-host sendiri Anda dapat melihatnya dan memercayainya di Pengaturan → Penyimpanan.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Sertifikat forge tidak tepercaya — ditandatangani sendiri, kedaluwarsa, atau diterbitkan atas nama lain.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Sertifikat endpoint tidak tepercaya — ditandatangani sendiri, kedaluwarsa, atau diterbitkan atas nama lain.',
  'creditcardnummer': 'nomor kartu kredit',
  'beveiligingscode van een creditcard': 'kode keamanan kartu (CVV)',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'data di catatan pembicara — tak terlihat di slide, tetapi ikut diekspor',
  'Certificaat vertrouwen?': 'Percayai sertifikat ini?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Sertifikat server ini tidak ditandatangani oleh penerbit yang diakui. Itu wajar untuk server yang di-host sendiri, tetapi begitu pula tampilan koneksi yang disadap.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Bandingkan sidik jari di bawah dengan yang ditampilkan server Anda sendiri. Jika cocok, Anda berbicara dengan mesin yang benar.',
  'Uitgegeven aan': 'Diterbitkan untuk',
  'Uitgegeven door': 'Diterbitkan oleh',
  'Geldig tot': 'Berlaku hingga',
  'Vingerafdruk (SHA-256)': 'Sidik jari (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Hanya sertifikat ini yang dipercaya. Jika server menggantinya nanti, OciDeck akan bertanya lagi.',
  'Vertrouwen': 'Percayai',
  'Certificaat bekijken': 'Lihat sertifikat',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Tempat kamu menyimpan dan mencari presentasimu — folder di komputer ini, server WebDAV, bucket S3, dan repositori git bercampur. Seret sesuai urutan yang kamu mau: yang teratas dari satu jenis berlaku sebagai baku.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Penyimpanan S3: saat kamu terhubung ke sebuah bucket, endpoint, nama bucket, dan kunci aksesmu disimpan (kunci rahasia disimpan aman di gantungan kunci sistemmu) dan presentasi yang kamu buka atau simpan dikirim ke layanan penyimpanan tersebut.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Penyimpanan Git: saat kamu terhubung ke sebuah repositori, token aksesmu disimpan (aman di gantungan kunci sistemmu) dan presentasi yang kamu simpan dikirim ke server tersebut sebagai commit. Salinan kerja repositori tetap tidak terenkripsi di perangkat ini.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Nama penyakit tidak tersedia untuk bahasa dek ini. Agama, pandangan politik, dan istilah serikat pekerja dikenali, dan pola dengan digit periksa (NIK, IBAN, paspor) selalu bekerja — tetapi jangan mengandalkan diagnosis ditemukan.',
  'niet getest': 'belum diuji',
  'Werkte op': 'Berhasil pada',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Anda sudah masuk, tetapi tidak punya akses di sini. Kata sandi bukan masalahnya — mintalah hak atas folder ini kepada administrator.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Token Anda valid, tetapi tidak diizinkan melakukan ini. Beri lebih banyak hak, atau tunggu jika forge menerapkan batas.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Token valid, tetapi tidak diizinkan melakukan ini — beri lebih banyak hak pada repositori.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Sudah masuk, tetapi tanpa akses — kata sandi bukan masalahnya. Mintalah hak atas folder ini.',
  'Lexiconlicenties: wat er nog nagevraagd moet worden':
      'Lisensi leksikon: apa yang masih perlu ditanyakan',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Ini tampak seperti URL DAV lengkap. Untuk Nextcloud, OciDeck menurunkan jalur itu sendiri — di sini hanya server yang perlu diisi.',
  'Overnemen': 'Terapkan',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV belum diatur dengan benar — periksa data server di Pengaturan → Penyimpanan.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Repositori git belum diatur dengan benar — periksa server, pemilik, dan repositori di Pengaturan → Penyimpanan.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Nama server forge tidak ada, atau tidak dapat dicari. Periksa URL server dari salah ketik.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Forge ini memiliki alamat privat atau LAN. Tandai sebagai internal tepercaya di Pengaturan → Penyimpanan.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Forge tidak dapat dijangkau — periksa koneksi Anda dan URL server.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Masuk ke forge gagal. Periksa token Anda: ia butuh akses baca ke repositori, dan akses tulis untuk menyimpan.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Tidak ditemukan di repositori — atau token Anda tidak boleh melihatnya.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Forge mengembalikan kesalahan. Coba lagi nanti.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
